import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-09-20","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-09-20","date":"2023-09-20T00:00:00.000Z","updated":"2023-10-04T00:00:00.000Z","tags":["Ceph","RGW","SNS 主题策略","持久通知性能","Kafka"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-20.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-20.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-20.md"};function o(n,a,s,h,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-每周-rgw-会议" tabindex="-1">会议主题：每周 RGW 会议 <a class="header-anchor" href="#会议主题-每周-rgw-会议" aria-label="Permalink to &quot;会议主题：每周 RGW 会议&quot;">​</a></h4><h4 id="日期-2023-09-20" tabindex="-1">日期：2023-09-20 <a class="header-anchor" href="#日期-2023-09-20" aria-label="Permalink to &quot;日期：2023-09-20&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>通知和 SNS 主题策略</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>Matt 介绍了关于通知和 SNS 主题策略的讨论，涉及 IAM 和 S3 策略，特别是 SNS API 的使用。</li><li>讨论了服务控制策略（SCP）和站点控制策略（SCP），这些策略可能需要通过扩展 API 或仪表板来支持。</li></ul></li><li><strong>决定事项</strong>： <ul><li>计划实现 SNS 主题策略，并考虑通过 RGW 管理命令和 API 来设置，如果标准 IAM 或 S3 REST API 不支持。</li></ul></li><li><strong>后续行动</strong>： <ul><li>继续探讨和实现 SNS 主题策略，并考虑添加相关 API 扩展。</li></ul></li></ul></li><li><p><strong>持久通知的性能</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>Yuvall 介绍了持久通知性能的 PR，讨论了当前使用单个工作线程从队列读取通知并发送至 Kafka 的机制。</li><li>讨论了增加更多工作线程的可能性，以及这可能带来的性能影响。</li></ul></li><li><strong>决定事项</strong>： <ul><li>认为增加更多工作线程可能不会显著提升性能，因为瓶颈可能在写入队列的操作。</li></ul></li><li><strong>后续行动</strong>： <ul><li>考虑添加更多 Kafka 客户端统计信息，以更好地理解系统性能和潜在瓶颈。</li><li>进行测试以验证单线程是否是瓶颈，并评估增加线程的影响。</li></ul></li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了队列填充的两种场景：队列未及时清空和 Kafka 代理响应慢。</li><li>提出了通过增加 Kafka 客户端统计信息来更好地诊断问题。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><ul><li>会议决定继续探索和实现 SNS 主题策略，并通过增加 Kafka 客户端统计信息来优化持久通知的性能。</li><li>将继续进行性能测试，以验证单线程是否是瓶颈，并评估增加线程的影响。</li></ul><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>下次会议将继续讨论相关议题，并根据测试结果调整优化策略。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢所有参会人员，下次会议再见。</li></ul>',14)])])}const g=l(r,[["render",o]]);export{_ as __pageData,g as default};
